<script setup lang="ts">
const auth=useAuth(),{notify,loginOpen}=useForum()
const statusNames:Record<string,string>={published:'已发布',hidden:'已隐藏',deleted:'已删除',active:'正常',disabled:'已禁用'}
const posts=ref<{id:string,title:string,status:string,pinned?:boolean,featured?:boolean}[]>([]),error=ref('')
const allowed=computed(()=>auth.user.value&&auth.user.value.role!=='member')
type AdminAsset={id:string,status:'active'|'hidden',width:number,height:number,createdAt:number,uploader:string,ownerStatus:string}
const replyItems=ref<{id:string,content:string,status:string,author:string}[]>([]),assets=ref<AdminAsset[]>([]),assetBusy=ref('')
async function load(){await auth.initialize();if(!allowed.value)return;try{posts.value=await auth.request('/admin/posts');replyItems.value=await auth.request('/admin/replies');assets.value=await auth.request('/admin/assets')}catch(e){error.value=(e as Error).message}}
async function editPost(id:string,patch:Record<string,unknown>){try{await auth.request('/posts/'+id,patch,'PATCH');await load();notify('内容状态已更新。')}catch(e){error.value=(e as Error).message}}
async function moderateAsset(asset:AdminAsset){
 if(assetBusy.value)return
 const viewer=auth.user.value?.id,status=asset.status==='active'?'hidden':'active'
 assetBusy.value=asset.id;error.value=''
 try{const result=await auth.request<{message:string}>('/admin/assets/'+asset.id,{status},'PATCH');if(viewer!==auth.user.value?.id)return;asset.status=status;notify(result.message)}
 catch(e){error.value=(e as Error).message;notify('图片操作失败：'+error.value)}
 finally{assetBusy.value=''}
}
function uploadedAt(value:number){return new Date(Number(value)).toLocaleString('zh-CN')}
async function moderateReply(id:string,status:string){try{await auth.request('/admin/replies/'+id,{status},'PATCH');await load()}catch(e){error.value=(e as Error).message}}
onMounted(load)
watch(()=>auth.user.value?.id,load)
</script>
<template><div class="award-admin-page"><h1>社区管理</h1><template v-if="allowed"><p class="award-field-help">内容管理操作会记录操作日志。</p><div class="admin-page-links"><NuxtLink to="/admin/site" class="button secondary">站点配置</NuxtLink><NuxtLink to="/admin/community" class="button secondary">动态与相册</NuxtLink><NuxtLink to="/admin/awards" class="button secondary">十二橙器活动管理</NuxtLink><NuxtLink to="/admin/accounts" class="button secondary">账号权限</NuxtLink></div><section class="award-admin-card"><h2>帖子管理</h2><article v-for="post in posts" :key="post.id" class="admin-content-row"><NuxtLink :to="'/post/'+post.id">{{ post.title }}</NuxtLink><span>{{ statusNames[post.status] }}</span><button @click="editPost(post.id,{status:post.status==='published'?'hidden':'published'})">{{ post.status==='published'?'隐藏':'恢复' }}</button><button @click="editPost(post.id,{pinned:!post.pinned})">{{ post.pinned?'取消置顶':'置顶' }}</button><button @click="editPost(post.id,{featured:!post.featured})">{{ post.featured?'取消精选':'精选' }}</button></article></section><section class="award-admin-card"><h2>回复管理</h2><article v-for="item in replyItems" :key="item.id" class="admin-content-row"><span>{{ item.author }}</span><p>{{ item.content }}</p><button @click="moderateReply(item.id,item.status==='published'?'hidden':'published')">{{ item.status==='published'?'隐藏':'恢复' }}</button></article></section><section class="award-admin-card" aria-labelledby="uploaded-images-heading"><h2 id="uploaded-images-heading">上传图片</h2><p class="award-field-help">展示上传记录，包含头像及帖子配图。隐藏图片仅供管理员预览，恢复后重新公开。</p><article v-for="asset in assets" :key="asset.id" class="admin-content-row admin-asset-row" :data-asset-id="asset.id" :aria-busy="assetBusy===asset.id"><SafeImage :key="asset.id+asset.status" class="admin-asset-preview" :src="'/api/admin/assets/'+asset.id" :alt="asset.status==='hidden'?'已隐藏图片的管理员预览':'上传图片预览'" width="80" height="80" /><div class="admin-asset-info"><span>{{ asset.width }} × {{ asset.height }} · {{ statusNames[asset.status] }}</span><small>{{ asset.uploader }} · {{ uploadedAt(asset.createdAt) }}</small><small v-if="asset.ownerStatus==='deleted'">上传者已注销，图片不能恢复。</small></div><button class="button secondary" :disabled="!!assetBusy||asset.ownerStatus==='deleted'" @click="moderateAsset(asset)">{{ assetBusy===asset.id?'处理中…':asset.status==='active'?'隐藏图片':'恢复图片' }}</button></article></section></template><div v-else class="empty-state"><p>需要管理员账号。</p><button class="button primary" @click="loginOpen=true">登录</button></div><p v-if="error" class="form-error" role="alert">{{ error }}</p></div></template>
<style scoped>h1,h2{font-family:var(--serif);margin:1rem 0}.award-admin-card{margin-top:1rem}.admin-page-links{display:flex;flex-wrap:wrap;gap:.75rem}.admin-content-row{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;padding:.8rem 0;border-bottom:1px solid var(--line);font-size:.75rem}.admin-content-row>a,.admin-content-row>strong{flex:1;min-width:10rem}.admin-content-row>button{color:var(--orange);font-size:.65rem}.admin-content-row>span{color:var(--subtle);font-size:.65rem}.admin-asset-preview{width:80px;height:80px;object-fit:cover;border-radius:.4rem;flex-shrink:0}.admin-asset-info{display:grid;gap:.35rem;flex:1;min-width:9rem;color:var(--subtle)}.admin-asset-info small{font-size:.625rem;line-height:1.6}</style>
